export function releaseStoryMusicEnvelope(fadeSeconds = 0.12): void {
  refreshRuntime();
  const now = getMusicAudioTime();
  if (now === null || fadeSeconds <= 0) {
    setMusicSceneEnvelopeImmediate(1);
  } else {
    const scheduledAt = scheduleMusicSceneEnvelope(
